entries[23632] = { ["name"] = "Pläne: Teufelsstahlschneide", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer Teufelsstahlschneide.\nBenötigt Schmiedekunst der Scherbenwelt (65)\nVerkaufspreis:\nTeufelsstahlschneide\nWird beim Anlegen gebunden\nZweihändig Axt\n6 - 13 Schaden Geschwindigkeit 3.60\n(2.6 Schaden pro Sekunde)\n+4 Stärke\nErhöht Eure kritische Trefferwertung um + 4.\nHaltbarkeit 120 / 120\nVerkaufspreis:\nBenötigt Khoriumbarren (10), Teufelsstahlbarren (10), Urmacht (8), Urnether (2)" }
entries[23633] = { ["name"] = "Pläne: Runenverzierter Hammer", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines runenverzierten Hammers.\nBenötigt Schmiedekunst der Scherbenwelt (65)\nVerkaufspreis:\nRunenverzierter Hammer\nWird beim Anlegen gebunden\nEinhändig Streitkolben\n4 - 6 Schaden Geschwindigkeit 2.60\n(1.9 Schaden pro Sekunde)\n+2 [Beweglichkeit oder Stärke]\n+2 Ausdauer\nHaltbarkeit 110 / 110\nVerkaufspreis:\nBenötigt Khoriumbarren (10), Teufelsstahlbarren (10), Urmacht (8), Urnether (2)" }
