entries[23638] = { ["name"] = "Pläne: Geringer Zauberschutz der Abschirmung", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines geringen Zauberschutzes der Abschirmung.\nBenötigt Schmiedekunst der Scherbenwelt (40)\nVerkaufspreis:\nGeringer Zauberschutz der Abschirmung\nBenutzen: Bringt den geringen Zauberschutz der Abschirmung an einem Schild an. Dieser Zauberschutz absorbiert bis zu 57 Schaden bevor er schwindet. Kann nicht von Charakteren über Stufe 49 verwendet werden.\nVerkaufspreis:\nBenötigt Adamantitbarren" }
entries[23639] = { ["name"] = "Pläne: Großer Zauberschutz der Abschirmung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines großen Zauberschutzes der Abschirmung.\nBenötigt Schmiedekunst der Scherbenwelt (75)\nVerkaufspreis:\nGroßer Zauberschutz der Abschirmung\nBenutzen: Bringt den großen Zauberschutz der Abschirmung an einem Schild an. Dieser Zauberschutz absorbiert bis zu 229 Schaden bevor er schwindet. Kann nicht von Charakteren über Stufe 49 verwendet werden.\nVerkaufspreis:\nBenötigt Eterniumbarren" }
