entries[23799] = { ["name"] = "Bauplan: Adamantitgewehr", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Adamantitgewehrs.\nBenötigt Ingenieurskunst der Scherbenwelt (50)\nVerkaufspreis:\nAdamantitgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n5 - 11 Schaden Geschwindigkeit 3.00\n(2.7 Schaden pro Sekunde)\n+5 Beweglichkeit\n+7 Ausdauer\nHaltbarkeit 85 / 85\nVerkaufspreis:\nBenötigt Teufelseisengehäuse (3), Adamantitrahmen (2), Eine Handvoll Teufelseisenbolzen (4)\nOptionale Reagenzien: [] (#48)" }
entries[23800] = { ["name"] = "Bauplan: Teufelsstahlschießeisen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Teufelsstahlschießeisens.\nBenötigt Ingenieurskunst der Scherbenwelt (60)\nVerkaufspreis:\nTeufelsstahlschießeisen\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n5 - 11 Schaden Geschwindigkeit 3.00\n(2.7 Schaden pro Sekunde)\n+4 Beweglichkeit\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 7.\nHaltbarkeit 100 / 100\nVerkaufspreis:\nBenötigt Gehärtetes Adamantitrohr , Teufelsstahlstabilisator (4), Eine Handvoll Teufelseisenbolzen (4)\nOptionale Reagenzien: [] (#48)" }
