entries[23802] = { ["name"] = "Bauplan: Verschnörkeltes Khoriumgewehr", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines verschnörkelten Khoriumgewehrs.\nBenötigt Ingenieurskunst der Scherbenwelt (75)\nVerkaufspreis:\nVerschnörkeltes Khoriumgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n5 - 11 Schaden Geschwindigkeit 3.00\n(2.7 Schaden pro Sekunde)\n+5 Beweglichkeit\nErhöht Eure kritische Trefferwertung um + 7.\nHaltbarkeit 100 / 100\nVerkaufspreis:\nBenötigt Gehärtetes Adamantitrohr (2), Khoriumbarren (12), Eine Handvoll Teufelseisenbolzen (4), Edeltopas (2)\nOptionale Reagenzien: [] (#48)" }
entries[23803] = { ["name"] = "Bauplan: Zahnradbrille", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer Zahnradbrille.\nBenötigt Ingenieurskunst der Scherbenwelt (40)\nVerkaufspreis:\nZahnradbrille\nWird beim Anlegen gebunden\nKopf Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+5 Ausdauer\nHaltbarkeit 85 / 85\nBenötigt Ingenieurskunst der Scherbenwelt (1)\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (4), Blutgranat (2), Arkaner Staub (8)\nOptionale Reagenzien: [] (#47)" }
entries[23804] = { ["name"] = "Bauplan: Energieverstärkungsbrille", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer Energieverstärkungsbrille.\nBenötigt Ingenieurskunst der Scherbenwelt (40)\nVerkaufspreis:\nEnergieverstärkungsbrille\nWird beim Anlegen gebunden\nKopf Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nHaltbarkeit 85 / 85\nBenötigt Ingenieurskunst der Scherbenwelt (1)\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (4), Flammenspessarit (2), Arkaner Staub (8)\nOptionale Reagenzien: [] (#47)" }
entries[23805] = { ["name"] = "Bauplan: Ultraspektropische Enthüllungsbrille", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer ultraspektropischen Enthüllungsbrille.\nBenötigt Ingenieurskunst der Scherbenwelt (50)\nVerkaufspreis:\nUltraspektropische Enthüllungsbrille\nWird beim Anlegen gebunden\nKopf Stoff\n3 Rüstung\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Tempowertung um + 6.\n+ 4 Vielseitigkeit\nHaltbarkeit 85 / 85\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\nBenötigt Ingenieurskunst der Scherbenwelt (1)\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (4), Khoriumbarren (2), Tiefenperidot (2), Kleiner Prismasplitter (2)\nOptionale Reagenzien: [] (#47)" }
entries[23806] = { ["name"] = "Bauplan: Extremsichtbrille", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung einer Extremsichtbrille.\nBenötigt Ingenieurskunst der Scherbenwelt (60)\nVerkaufspreis:\nExtremsichtbrille\nWird beim Anlegen gebunden\nKopf Leder\n5 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\nErhöht Eure kritische Trefferwertung um + 4.\nHaltbarkeit 85 / 85\nBenutzen: Erhöht 15 Sek. lang Eure Verstohlenheitsaufdeckung. (2 Min Abklingzeit)\nBenötigt Ingenieurskunst der Scherbenwelt (1)\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (4), Khoriumbarren (2), Nachtauge (2), Großer Prismasplitter (2)\nOptionale Reagenzien: [] (#47)" }
entries[23807] = { ["name"] = "Bauplan: Adamantitzielfernrohr", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Adamantitzielfernrohrs.\nBenötigt Ingenieurskunst der Scherbenwelt (35)\nVerkaufspreis:\nAdamantitzielfernrohr\nBenutzen: Bringt dauerhaft ein Zielfernrohr an einem Bogen oder einer Schusswaffe an, das den damit verursachten Schaden um 5 erhöht.\n\nDurch das Anbringen des Fernrohrs an einer Distanzwaffe wird diese seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:\nBenötigt Adamantitbarren (8), Golddraenit (2)" }
entries[23808] = { ["name"] = "Bauplan: Khoriumzielfernrohr", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Khoriumzielfernrohrs.\nBenötigt Ingenieurskunst der Scherbenwelt (60)\nVerkaufspreis:\nKhoriumzielfernrohr\nBenutzen: Bringt dauerhaft ein Zielfernrohr an einem Bogen oder einer Schusswaffe an, das den damit verursachten Schaden um 6 erhöht. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:\nBenötigt Gehärtetes Adamantitrohr , Khoriumbarren (4), Dämmerstein (2)" }
entries[23809] = { ["name"] = "Bauplan: Geeichtes Eterniumzielfernrohr", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines geeichten Eterniumzielfernrohrs.\nBenötigt Ingenieurskunst der Scherbenwelt (75)\nVerkaufspreis:\nGeeichtes Eterniumzielfernrohr\nBenutzen: Bringt dauerhaft ein Zielfernrohr an einem Bogen oder einer Schusswaffe an, das ihren kritischen Trefferwert um 13 erhöht.\n\nDurch das Anbringen des Fernrohrs an einer Distanzwaffe wird diese seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:\nBenötigt Gehärtetes Adamantitrohr (2), Teufelsstahlstabilisator (6), Stern der Elune (2)" }
entries[23810] = { ["name"] = "Bauplan: Krachbummroboter", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Krachbummroboters.\nBenötigt Ingenieurskunst der Scherbenwelt (25)\nVerkaufspreis:\nKrachbummroboter\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Einen robotischen Begleiter zu beschwören, der gegen andere Roboter kämpfen wird. (3 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Adamantitrahmen , Teufelseisengehäuse (2), Goldkraftkern , Eine Handvoll Teufelseisenbolzen (2)" }
entries[23811] = { ["name"] = "Bauplan: Weißes Rauchsignal", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines weißen Rauchsignals.\nBenötigt Ingenieurskunst der Scherbenwelt (35)\nVerkaufspreis:\nWeißes Rauchsignal\nBenutzen: Wirft ein weißes Rauchsignal in ein bestimmtes Gebiet. Hält 5 Min. lang an. (5 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Elementarsprengpulver , Netherstoff" }
entries[23812] = { ["name"] = "Bauplan: Rotes Rauchsignal", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines roten Rauchsignals.\nBenötigt Ingenieurskunst der Scherbenwelt (35)\nVerkaufspreis:\nRotes Rauchsignal\nBenutzen: Wirft ein rotes Rauchsignal in ein bestimmtes Gebiet. Hält 5 Min. lang an. (5 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Elementarsprengpulver , Netherstoff , Roter Farbstoff" }
entries[23813] = { ["name"] = "Bauplan: Blaues Rauchsignal", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines blauen Rauchsignals.\nBenötigt Ingenieurskunst der Scherbenwelt (35)\nVerkaufspreis:\nBlaues Rauchsignal\nBenutzen: Wirft ein blaues Rauchsignal in ein bestimmtes Gebiet. Hält 5 Min. lang an. (5 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Elementarsprengpulver , Netherstoff , Blauer Farbstoff" }
entries[23814] = { ["name"] = "Bauplan: Grünes Rauchsignal", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines grünen Rauchsignals.\nBenötigt Ingenieurskunst der Scherbenwelt (35)\nBenötigt Expedition des Cenarius\n- Freundlich\nVerkaufspreis:\nGrünes Rauchsignal\nBenutzen: Wirft ein grünes Rauchsignal in ein bestimmtes Gebiet. Hält 5 Min. lang an. (5 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Elementarsprengpulver , Netherstoff , Grüner Farbstoff" }
entries[23815] = { ["name"] = "Ruinierter Bauplan", ["text"] = "\"Dieser Bauplan wurde von den Elementen zerstört.\"\nVerkaufspreis:" }
entries[23816] = { ["name"] = "Bauplan: Werkzeugkasten aus Teufelseisen", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Werkzeugkastens aus Teufelseisen.\nBenötigt Ingenieurskunst der Scherbenwelt (25)\nVerkaufspreis:\nWerkzeugkasten aus Teufelseisen\nWird beim Anlegen gebunden\n24 Platz Ingenieurstasche\nVerkaufspreis:\nBenötigt Teufelseisengehäuse , Teufelseisenbarren (5), Eine Handvoll Teufelseisenbolzen (2)" }
entries[23817] = { ["name"] = "Bauplan: Werkzeugkasten aus Titan", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Werkzeugkastens aus Titan.\nBenötigt Ingenieurskunst von Nordend (30)\nVerkaufspreis:\nWerkzeugkasten aus Titan\nWird beim Anlegen gebunden\n32 Platz Ingenieurstasche\n\"Unterteilt in kleine Fächer, die sich perfekt für die Aufbewahrung von Ingenieursbedarf eignen.\"\nVerkaufspreis:\nBenötigt Saronitbarren (8), Titanbarren (8), Eine Handvoll Kobaltbolzen (4)" }
entries[23818] = { ["name"] = "Übersetzungsfibel der Tannenruhfeste", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Lehrt Euch, die Symbole der Furbolgs der Tannenruhfeste besser zu verstehen.\n\"Die Fibel enthält Übersetzungen für die Grundsymbole aus der Furbolgsprache.\"" }
entries[23819] = { ["name"] = "Elementare Zephyriumladung", ["text"] = "Benutzen: Sprengt bis auf die stärksten alle verschlossenen Türen und Truhen auf.\nBenötigt Ingenieurskunst der Scherbenwelt (50)\nVerkaufspreis:" }
entries[23820] = { ["name"] = "Kleintiervergrößerer", ["text"] = "Benutzen: Vergrößert ein Kleintier auf das Doppelte seiner normalen Größe. (15 Sek. Abklingzeit)\nBenötigt Ingenieurskunst der Scherbenwelt (25)\n\"Die Anwendungsmöglichkeiten für dieses Gerät sind nahezu unbegrenzt.\"\nVerkaufspreis:" }
entries[23821] = { ["name"] = "Schockdrosselnder Partikelextraktor", ["text"] = "Einzigartig\nBenutzen: Extrahiert Gas aus einer in der Nähe befindlichen Gaswolke.\nZeigt die Position aller nahen Gaswolken auf der Minikarte an, solang sich der Partikelextraktor in Eurem Inventar befindet.\nBenötigt Ingenieurskunst der Scherbenwelt (5)\nVerkaufspreis:" }
entries[23822] = { ["name"] = "Heiltrankeinspritzung", ["text"] = "Benutzen: Stellt 569 Gesundheit wieder her. Erhöhter Effekt für Ingenieure! (5 Min Abklingzeit)\n20 Aufladungen\n\"Heutzutage wird so etwas nicht mehr hergestellt...\"\nVerkaufspreis:" }
entries[23823] = { ["name"] = "Manatrankeinspritzung", ["text"] = "Benutzen: Stellt 682 Mana wieder her. Erhöhter Effekt für Ingenieure! (5 Min Abklingzeit)\n20 Aufladungen\n\"Heutzutage wird so etwas nicht mehr hergestellt...\"\nVerkaufspreis:" }
entries[23824] = { ["name"] = "Raketenstiefel Xtrem", ["text"] = "Wird beim Anlegen gebunden\nFüße Leder\n4 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\nHaltbarkeit 65 / 65\nBenutzen: Die Raketenstiefel aktivieren, um einen gewaltigen Geschwindigkeitsschub zu erhalten. (5 Min Abklingzeit)\nBenötigt Ingenieurskunst der Scherbenwelt (1)\nVerkaufspreis:" }
entries[23825] = { ["name"] = "Gürtel der fast perfekten Unverwundbarkeit", ["text"] = "Wird beim Anlegen gebunden\nTaille Stoff\n2 Rüstung\n+2 Ausdauer\n+ 7 Vielseitigkeit\nHaltbarkeit 50 / 50\nBenutzen: Schützt Euch mit einem Energieschild, der 8 Sek. lang 217 Schaden aufhält. (5 Min Abklingzeit)\nBenötigt Ingenieurskunst der Scherbenwelt (1)\n\"Der Schutz ist nicht immer wirksam. In SELTENEN Fällen kann der Träger zusätzlichen Schaden erleiden.\"\nVerkaufspreis:" }
entries[23826] = { ["name"] = "Die Größere", ["text"] = "Benutzen: Fügt Zielen innerhalb von 10 Metern 46 Feuerschaden zu und macht sie 5 Sek. lang handlungsunfähig. Jeglicher Schaden bricht den Effekt ab. Unzuverlässig gegen Ziele über Stufe 49. (1 Min Abklingzeit)\nBenötigt Ingenieurskunst der Scherbenwelt (25)\nVerkaufspreis:" }
entries[23827] = { ["name"] = "Super Pioniersprengladung", ["text"] = "Benutzen: Explodiert bei Zündung, fügt allen gegnerischen Einheiten in der Nähe 69 Feuerschaden zu und Euch 52 Schaden. (5 Min Abklingzeit)\nBenötigt Ingenieurskunst der Scherbenwelt (40)\nVerkaufspreis:" }
entries[23828] = { ["name"] = "Gnomische Machtschutzbrille", ["text"] = "Wird beim Aufheben gebunden\nKopf Stoff\n3 Rüstung\n+5 Intelligenz\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nHaltbarkeit 100 / 100\nBenötigt Ingenieurskunst der Scherbenwelt (1)\nVerkaufspreis:" }
entries[23829] = { ["name"] = "Gnomische Kampfschutzbrille", ["text"] = "Wird beim Aufheben gebunden\nKopf Leder\n5 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nHaltbarkeit 100 / 100\nBenötigt Ingenieurskunst der Scherbenwelt (1)\nVerkaufspreis:" }
entries[23830] = { ["name"] = "Kloppers Ausrüstung", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Ausrüstung scheint in Ordnung zu sein.\"" }
entries[23831] = { ["name"] = "Goblindampfpanzersteuerung", ["text"] = "Benutzen: Die Kontrolle über einen Dampfpanzer übernehmen.\n50 Aufladungen\nVerkaufspreis:" }
entries[23832] = { ["name"] = "Gnomische Dampfpanzersteuerung", ["text"] = "Benutzen: Die Kontrolle über einen Dampfpanzer übernehmen.\n50 Aufladungen\nVerkaufspreis:" }
entries[23833] = { ["name"] = "Kunstloses Murlocmesser", ["text"] = "Questgegenstand\n\"Eine grob behauene Steinklinge an einem langen Stab mit einer Sehne.\"" }
entries[23834] = { ["name"] = "Kunstloser Murlocgötze", ["text"] = "Questgegenstand\n\"Ein grob geschnitzter Götze, der keine erkennbare Figur darstellt.\"" }
entries[23835] = { ["name"] = "Gnomischer Geflügelisierer", ["text"] = "Wird beim Anlegen gebunden\nSchmuck\n+8 Ausdauer\nBenutzen: Verwandelt den Gegner 15 Sek. lang in ein Huhn. Das heißt, falls die Transmogrifikationspolarität nicht verwechselt wurde... (5 Min Abklingzeit)\nBenötigt Ingenieurskunst der Scherbenwelt (40)\nBenötigt Gnomeningenieur\nVerkaufspreis:" }
entries[23836] = { ["name"] = "Goblinraketenwerfer", ["text"] = "Wird beim Anlegen gebunden\nSchmuck\n+8 Ausdauer\nBenutzen: Feuert eine mächtige Rakete auf den Gegner, die 18 Schaden verursacht und ihn 3 Sek. lang betäubt. Das Ding hat aber einen ziemlichen Rückstoß... (2 Min Abklingzeit)\nBenötigt Ingenieurskunst der Scherbenwelt (50)\nBenötigt Gobliningenieur\nVerkaufspreis:" }
entries[23837] = { ["name"] = "Verwitterte Schatzkarte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Das Pergament ist vergilbt, verblichen und voller Löcher, dennoch ist das Meiste noch lesbar.\"" }
entries[23838] = { ["name"] = "Verzauberter Helm des Vorarbeiters", ["text"] = "Wird beim Aufheben gebunden\nKopf Stoff\n3 Rüstung\n+3 Intelligenz\n+7 Ausdauer\nHaltbarkeit 100 / 100\nAnlegen: +10% Betäubungswiderstand.\nBenötigt Ingenieurskunst der Scherbenwelt (1)\nVerkaufspreis:" }
entries[23839] = { ["name"] = "Verstärkter Helm des Vorarbeiters", ["text"] = "Wird beim Aufheben gebunden\nKopf Kette\n7 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nHaltbarkeit 100 / 100\nAnlegen: Erhöht Eure Chance, Betäubungs- und Desorientierungseffekten zu widerstehen, um 10%.\nBenötigt Ingenieurskunst der Scherbenwelt (1)\nVerkaufspreis:" }
entries[23841] = { ["name"] = "Gnomisches Flammengeschütz", ["text"] = "Benutzen: Errichtet schnell ein gnomisches Flammengeschütz zu Euren Füßen, das automatisch angreifen wird. Meistens Gegner. Das Geschütz fällt nach 45 Sek. in sich zusammen. (1 Min Abklingzeit)\nBenötigt Ingenieurskunst der Scherbenwelt (25)\nVerkaufspreis:" }
entries[23843] = { ["name"] = "Luftwirbel", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein Teil von Susurrus, der auf irgendeine Weise an Eure Hand gebunden bleibt.\"" }
