entries[23857] = { ["name"] = "Vermächtnis des Bergkönigs", ["text"] = "Karazhan\nEinzigartig\nBenutzen: Bricht das Siegel des Buches und gewährt Euch eine Chance, Eure Rüstung und Euren Magiewiderstand zu erhöhen, wenn Ihr im Gefecht getroffen werdet. (Procchance: 3%)\n\"Die Essenz dieses Buchs ist an Karazhan gebunden.\"" }
entries[23858] = { ["name"] = "Angesengte Seite", ["text"] = "\"Nachdem das Siegel von 'Vermächtnis des Bergkönigs' gebrochen wurde, verbleibt noch diese Seite.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[23859] = { ["name"] = "Glyphe vom Monument der Nazzivus", ["text"] = "Questgegenstand\nEinzigartig\n\"Finster aussehende Kreaturen in Begleitung einiger humanoider Gestalten bilden zusammen eine Art Erzählung.\"" }
