entries[23862] = { ["name"] = "Erlösung des Gefallenen", ["text"] = "Karazhan\nEinzigartig\nBenutzen: Bricht das Siegel des Buches und gewährt Euren Heilzaubern eine Chance, einen geisterhaften Verbündeten zu beschwören. (Procchance: 3%)\n\"Die Essenz dieses Buchs ist an Karazhan gebunden.\"" }
entries[23863] = { ["name"] = "Verderbter Kristall", ["text"] = "Questgegenstand\n\"Der Kristall pulsiert in einem aggressiven Rot. Man kann kaum glauben, dass dies einmal ein Teil der Exodar war.\"" }
entries[23864] = { ["name"] = "Qual des Worgen", ["text"] = "Karazhan\nEinzigartig\nBenutzen: Bricht das Siegel des Buches und gewährt Euch eine Chance, bei Nahkampf- und Distanzangriffen zusätzlichen Schattenschaden zu verursachen.\n\"Die Essenz dieses Buchs ist an Karazhan gebunden.\"" }
entries[23865] = { ["name"] = "Zorn der Titanen", ["text"] = "Karazhan\nEinzigartig\nBenutzen: Bricht das Siegel des Buches und gewährt Euren offensiven Zaubern eine Chance, zusätzlichen Schaden zuzufügen. (Procchance: 3%, 30s Abklingzeit)\n\"Die Essenz dieses Buchs ist an Karazhan gebunden.\"" }
entries[23866] = { ["name"] = "Angesengte Seite", ["text"] = "\"Nachdem das Siegel von 'Erlösung des Gefallenen' gebrochen wurde, verbleibt noch diese Seite.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
