entries[24000] = { ["name"] = "Formel: Armschiene - Überragende Heilung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Überragende Heilung' bei Armschienen durchführt.\nArmschienen dauerhaft verzaubern, sodass die Zaubermacht um 4 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst der Scherbenwelt (25)\nBenötigt Thrallmar\n- Freundlich\nVerkaufspreis:" }
entries[24001] = { ["name"] = "Rezept: Elixier der erheblichen Beweglichkeit", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Elixiers der erheblichen Beweglichkeit.\nBenötigt Alchemie der Scherbenwelt\n(30)\nBenötigt Thrallmar\n- Wohlwollend\nVerkaufspreis:\nElixier der erheblichen Beweglichkeit\nBenutzen: Erhöht 1 Stunde lang die Beweglichkeit um 10 und den kritischen Trefferwert um 4 . Kampfelixier. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Terozapfen , Teufelsgras (2), Kristallphiole" }
entries[24002] = { ["name"] = "Pläne: Teufelsstahlschildstachel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Teufelsstahlschildstachels.\nBenötigt Schmiedekunst der Scherbenwelt (60)\nBenötigt Thrallmar\n- Ehrfürchtig\nVerkaufspreis:\nTeufelsstahlschildstachel\nBenutzen: Bringt einen Teufelsstahlstachel an Eurem Schild an, der bei jedem Blocken 3 Schaden verursacht. Kann nicht auf Gegenstände über Stufe 0 angewandt werden.\nVerkaufspreis:\nBenötigt Teufelsstahlbarren (4), Urfeuer (4), Urerde (4)" }
entries[24003] = { ["name"] = "Formel: Brust - Außergewöhnliche Werte", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Außergewöhnliche Werte' bei Brustrüstung durchführt.\nEine Brustrüstung dauerhaft verzaubern, sodass alle Werte um 534 erhöht werden. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst der Scherbenwelt (45)\nBenötigt Thrallmar\n- Respektvoll\nVerkaufspreis:" }
