entries[24172] = { ["name"] = "Vorlage: Kronenreif der grünen Flamme", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Kronenreifs der grünen Flamme.\nBenötigt Juwelierskunst der Scherbenwelt\n(70)\nVerkaufspreis:\nKronenreif der grünen Flamme\nWird beim Anlegen gebunden\nKopf Stoff\n3 Rüstung\n+4 Intelligenz\n+4 Ausdauer\nHaltbarkeit 100 / 100\nAnlegen: Chance bei erfolgreichem Zauberwirken im Verlauf von 10 Sek. 90 Mana wiederherzustellen. (Procchance: 75%, 25s Abklingzeit)\nVerkaufspreis:\nBenötigt Khoriumbarren (20), Urleben (20), Talasit (2), Quecksilberadamantit (5)" }
entries[24173] = { ["name"] = "Vorlage: Reif der arkanen Macht", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Reifs der arkanen Macht.\nBenötigt Juwelierskunst der Scherbenwelt\n(70)\nVerkaufspreis:\nReif der arkanen Macht\nWird beim Anlegen gebunden\nKopf Stoff\n3 Rüstung\n+3 Intelligenz\n+4 Ausdauer\n+ 4 Vielseitigkeit\nHaltbarkeit 100 / 100\nAnlegen: Chance von 2%, bei erfolgreichem Zauberwirken die Zaubermacht 15 Sek. lang um bis zu 7 zu erhöhen. (Procchance: 2%)\nVerkaufspreis:\nBenötigt Teufelsstahlbarren (20), Urmana (20), Stern der Elune (2), Quecksilberadamantit (5)" }
entries[24174] = { ["name"] = "Vorlage: Anhänger der Eisflamme", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Anhängers der Eisflamme.\nBenötigt Juwelierskunst der Scherbenwelt\n(60)\nBenötigt Hüter der Zeit\n- Respektvoll\nVerkaufspreis:\nAnhänger der Eisflamme\nWird beim Anlegen gebunden\nHals\n+2 Ausdauer\n+3 Feuerwiderstand\nBenutzen: Absorbiert 160 Feuerschaden, den in der Nähe befindliche Gruppenmitglieder erleiden. Hält 5 Min. lang an. (1 Stunde Abklingzeit)\n10 Aufladungen\nVerkaufspreis:\nBenötigt Teufelsstahlbarren (2), Urwasser (6), Urfeuer (4), Quecksilberadamantit" }
entries[24175] = { ["name"] = "Vorlage: Anhänger des Tauens", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Anhängers des Tauens.\nBenötigt Juwelierskunst der Scherbenwelt\n(60)\nBenötigt Unteres Viertel\n- Respektvoll\nVerkaufspreis:\nAnhänger des Tauens\nWird beim Anlegen gebunden\nHals\n+2 Ausdauer\n+3 Frostwiderstand\nBenutzen: Absorbiert von allen nahen Gruppenmitgliedern 160 Frostschaden. Hält 5 Min. lang an. (1 Stunde Abklingzeit)\n10 Aufladungen\nVerkaufspreis:\nBenötigt Teufelsstahlbarren (2), Urfeuer (6), Urwasser (4), Quecksilberadamantit" }
entries[24176] = { ["name"] = "Vorlage: Anhänger des Erlöschens", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Anhängers des Erlöschens.\nBenötigt Juwelierskunst der Scherbenwelt\n(60)\nBenötigt Die Seher\n- Respektvoll\nVerkaufspreis:\nAnhänger des Erlöschens\nWird beim Anlegen gebunden\nHals\n+2 Ausdauer\n+3 Naturwiderstand\nBenutzen: Absorbiert 160 Naturschaden, den in der Nähe befindliche Gruppenmitglieder erleiden. Hält 5 Min. lang an. (1 Stunde Abklingzeit)\n10 Aufladungen\nVerkaufspreis:\nBenötigt Teufelsstahlbarren (2), Urschatten (6), Urleben (4), Quecksilberadamantit" }
